def emit(path, rows, prefix):
    p = Path(path)
    p.unlink(missing_ok=True)
    out = []
    for i, r in enumerate(rows, start=1):
        if prefix == "CG":
            row = {"id": f"CG-{WP}-{i}", "title": r["title"], "source": SRC, "section": r["section"],
                   "description": r["description"], "evidence": r["evidence"], "type": r["type"],
                   "area": r["area"], "severity": r["severity"], "needed_by_wave": r["needed_by_wave"],
                   "legacy_ref": r.get("legacy_ref", "RWB-E1-001"), "owner_role": r["owner_role"],
                   "asm": f"ASM-{WP}-{i}", "proposed": r["proposed"], "wp": WP}
        else:
            row = {"id": f"ASM-{WP}-{i}", "text": r["text"], "why": r["why"], "read": r["read"],
                   "gap": f"CG-{WP}-{i}", "applied_in": r["applied_in"], "confidence": r["confidence"],
                   "confirm": r["confirm"], "impact": r["impact"], "wp": WP}
        out.append(row)
    p.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in out) + "\n", encoding="utf-8")
    print("wrote", p, len(out))


emit("_work/msr/gaps/B-DATA-20.jsonl", GAPS, "CG")
emit("_work/msr/assumptions/B-DATA-20.jsonl", ASSUMPTIONS, "ASM")
